def choose_move(observation):
    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))

    # Helper to compute step towards target from current position
    def step_towards(curr, targ):
        x, y = curr
        tx, ty = targ
        dx = 0 if tx == x else (1 if tx > x else -1)
        dy = 0 if ty == y else (1 if ty > y else -1)
        return [dx, dy]

    # Pursuit-Evasion: if pursuing, move toward opponent; otherwise head to farthest corner
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards((sx, sy), (ox, oy))
        corners = [
            [0, 0],
            [0, observation.get("grid_height", 1) - 1],
            [observation.get("grid_width", 1) - 1, 0],
            [observation.get("grid_width", 1) - 1, observation.get("grid_height", 1) - 1],
        ]
        # target farthest corner from opponent
        target = max(corners, key=lambda item: abs(item[0] - ox) + abs(item[1] - oy))
        return step_towards((sx, sy), (target[0], target[1]))

    # Territory control: move toward closest target (prefer unclaimed)
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return step_towards((sx, sy), (best[0], best[1]))

    # Resource collection: head toward nearest resource; if none, head toward opponent
    resources = observation.get("resources") or []
    if not resources:
        return step_towards((sx, sy), (ox, oy))

    best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
    return step_towards((sx, sy), (best[0], best[1]))

